INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091001, "風属性のキャラが４体以上編成されているとき、キャラの属性ボーナスが強化される。風属性以外の属性ボーナスを無効化する。", "風属性ボーナス特大アップ", 4100910, 14);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091002, "すべてのモンスターが一度の行動で受けるダメージ値を減衰させる。ダメージ値が上昇するほど減衰率も上昇する。", "ダメージ減衰", 4100910, 18);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091003, "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", "物理防御力（ダウン不可）アップ", 4100910, "boss_def_lower_limit");
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091004, "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", "魔法防御力（ダウン不可）アップ", 4100910, "boss_magic_def_lower_limit");
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091005, "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", "ＴＰダウンカット", 4100910, "boss_tp_down_cut");
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091006, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", "ＴＰ上昇ダウン", 4100910, 3);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES (10091007, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", "ＨＰ吸収ダウン", 4100910, 9);
